workflow.script:
export const meta = { name: 'pipeline-log', phases: [{ title: 'Process' }] }
phase('Process')
log('starting pipeline')
const results = await pipeline(args.items, async (item, original, index) => {
  const result = await agent('process:' + item, { label: 'item-' + index })
  if (!result.ok) throw new Error(result.error || 'failed')
  return result.output
}, async (output, original) => original === 'skip' ? Promise.reject(new Error('skip')) : output.toUpperCase())
log('pipeline settled')
return results
